BEGIN;
CREATE TYPE clinical_value_status AS ENUM ('OBSERVED','SURVEY_ESTIMATE','DERIVED_RATE','MULTIYEAR_AGGREGATE','PARTIAL','NOT_COMPARABLE','NOT_AVAILABLE','SUPPRESSED');
CREATE TYPE clinical_comparability_status AS ENUM ('ADMIT','ADMIT_WITH_LIMITATIONS','RESEARCH_ONLY','HOLD','REJECT','COMPARABLE','PARTIALLY_COMPARABLE','NOT_COMPARABLE','NOT_AVAILABLE');
CREATE TABLE diagnosis_group (group_id text PRIMARY KEY, group_name text NOT NULL, coding_system text NOT NULL, code_start text NOT NULL, code_end text NOT NULL, include_rule text NOT NULL, exclude_rule text, clinical_notes text, version text NOT NULL);
CREATE TABLE clinical_data_quality (quality_id bigserial PRIMARY KEY, domain text NOT NULL, dataset_version_id bigint REFERENCES dataset_version(dataset_version_id), comparability_status clinical_comparability_status NOT NULL, geography_level geography_level NOT NULL, age_group_original text, case_definition text NOT NULL, limitation text, method_id text NOT NULL);
CREATE TABLE pediatric_hospital_indicator (indicator_id bigserial PRIMARY KEY, observation_id bigint NOT NULL REFERENCES observation(observation_id), diagnosis_group_id text REFERENCES diagnosis_group(group_id), value_status clinical_value_status NOT NULL, comparability_status clinical_comparability_status NOT NULL, method_id text NOT NULL);
CREATE TABLE pediatric_emergency_activity (activity_id bigserial PRIMARY KEY, observation_id bigint NOT NULL REFERENCES observation(observation_id), facility_id text REFERENCES pediatric_facility(facility_id), definition text NOT NULL, value_status clinical_value_status NOT NULL, comparability_status clinical_comparability_status NOT NULL, method_id text NOT NULL);
CREATE TABLE perinatal_indicator (indicator_id bigserial PRIMARY KEY, observation_id bigint NOT NULL REFERENCES observation(observation_id), indicator_code text NOT NULL, numerator numeric, denominator numeric, value_status clinical_value_status NOT NULL, method_id text NOT NULL);
CREATE TABLE pediatric_mortality (mortality_id bigserial PRIMARY KEY, observation_id bigint NOT NULL REFERENCES observation(observation_id), cause_code text NOT NULL, numerator numeric, denominator numeric, suppressed boolean NOT NULL DEFAULT false, value_status clinical_value_status NOT NULL, method_id text NOT NULL);
CREATE TABLE child_health_survey_indicator (indicator_id bigserial PRIMARY KEY, observation_id bigint NOT NULL REFERENCES observation(observation_id), indicator_code text NOT NULL, sample_n integer, standard_error numeric, value_status clinical_value_status NOT NULL CHECK (value_status='SURVEY_ESTIMATE'), method_id text NOT NULL);
COMMIT;
